function Icon({ d, size = 16 }: { d: string; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      {d.split(" M").map((seg, i) => (
        <path key={i} d={i === 0 ? seg : `M${seg}`} />
      ))}
    </svg>
  );
}

function href(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  if (type === "website") return value.startsWith("http") ? value : `https://${value}`;
  return "#";
}

export function AuroraNameCard({ data, accentColor = "#6366f1" }: Props) {
  const { fullName, pronouns, jobTitle, company, companyLogoUrl, tagline, bio,
    avatarUrl, contacts, socialLinks, skills, featuredQuote, ctaLabel, ctaUrl } = data;

  return (
    <main className="min-h-screen w-full" style={{
      background: `radial-gradient(ellipse 80% 50% at 50% -10%, ${accentColor}30 0%, transparent 55%),
                   radial-gradient(ellipse 50% 40% at 85% 85%, #06b6d418 0%, transparent 50%),
                   linear-gradient(160deg, #05050b 0%, #080810 100%)`,
    }}>
      <div className="mx-auto flex min-h-screen max-w-sm flex-col justify-center px-4 py-10">
        <div className="overflow-hidden rounded-3xl" style={{
          background: "rgba(255,255,255,0.04)",
          border: "1px solid rgba(255,255,255,0.09)",
          backdropFilter: "blur(40px)",
          WebkitBackdropFilter: "blur(40px)",
          boxShadow: `0 40px 100px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,255,255,0.1)`,
        }}>
          {/* Hero band */}
          <div className="relative h-32 overflow-hidden" style={{
            background: `linear-gradient(135deg, ${accentColor}70 0%, ${accentColor}30 50%, #06b6d430 100%)`,
          }}>
            <div className="absolute inset-0" style={{
              backgroundImage: `radial-gradient(${accentColor}30 1px, transparent 1px)`,
              backgroundSize: "20px 20px",
            }} />
            {companyLogoUrl && (
              <div className="absolute right-4 bottom-3">
                <Image src={companyLogoUrl} alt={company} width={72} height={28}
                  className="h-7 w-auto object-contain brightness-0 invert opacity-70" />
              </div>
            )}
          </div>

          {/* Avatar */}
          <div className="-mt-14 px-6">
            <div className="relative mb-3 w-fit">
              <div className="h-[88px] w-[88px] overflow-hidden rounded-2xl ring-4 ring-neutral-950"
                style={{ boxShadow: `0 0 0 2px ${accentColor}` }}>
                {avatarUrl ? (
                  <Image src={avatarUrl} alt={fullName} width={88} height={88}
                    className="h-full w-full object-cover" priority />
                ) : (
                  <div className="flex h-full w-full items-center justify-center text-3xl font-black text-white"
                    style={{ background: `linear-gradient(135deg, ${accentColor}, #06b6d4)` }}>
                    {fullName.charAt(0)}
                  </div>
                )}
              </div>
            </div>

            <h1 className="text-2xl font-black leading-tight text-white">
              {fullName}
              {pronouns && <span className="ml-2 text-sm font-normal text-white/35"> · {pronouns}</span>}
            </h1>
            <p className="mt-0.5 text-sm font-semibold" style={{ color: accentColor }}>{jobTitle}</p>
            <p className="text-xs text-white/45">{company}</p>
            {tagline && (
              <p className="mt-3 text-[13px] leading-relaxed text-white/55 italic">&ldquo;{tagline}&rdquo;</p>
            )}
          </div>

          {/* Divider */}
          <div className="mx-6 my-4 h-px" style={{
            background: `linear-gradient(90deg, transparent, ${accentColor}50, transparent)`,
          }} />

          {bio && <p className="px-6 text-[13px] leading-relaxed text-white/60">{bio}</p>}

          {/* Contact rows */}
          {contacts.length > 0 && (
            <div className="mt-4 space-y-2 px-6">
              {contacts.map((c, i) => (
                <a key={i} href={href(c.type, c.value)}
                  target={c.type === "website" ? "_blank" : undefined}
                  rel={c.type === "website" ? "noopener noreferrer" : undefined}
                  className="group flex items-center gap-3 rounded-xl px-3 py-2.5 transition-all hover:scale-[1.01]"
                  style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.07)" }}>
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg"
                    style={{ background: `${accentColor}20`, color: accentColor }}>
                    <Icon d={SVG_PATHS[c.type] ?? SVG_PATHS.website} size={14} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-[10px] uppercase tracking-wider text-white/30">{c.label ?? c.type}</p>
                    <p className="truncate text-[13px] font-medium text-white/80">{c.value}</p>
                  </div>
                  <span className="text-white/20 transition-colors group-hover:text-white/50">
                    <Icon d={SVG_PATHS.arrow} size={13} />
                  </span>
                </a>
              ))}
            </div>
          )}

          {/* Social links */}
          {socialLinks.length > 0 && (
            <div className="mt-5 px-6">
              <p className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-white/25">Connect</p>
              <div className="flex flex-wrap gap-2">
                {socialLinks.map((s, i) => (
                  <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                    className="flex items-center gap-1.5 rounded-xl px-3 py-2 text-white/55 transition-all hover:text-white hover:scale-105"
                    style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.08)" }}>
                    {SVG_PATHS[s.platform] && <Icon d={SVG_PATHS[s.platform]} size={14} />}
                    {s.label && <span className="text-xs font-medium">{s.label}</span>}
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Skills */}
          {skills && skills.length > 0 && (
            <div className="mt-5 px-6">
              <p className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-white/25">Expertise</p>
              <div className="flex flex-wrap gap-1.5">
                {skills.map((s, i) => (
                  <span key={i} className="rounded-lg px-2.5 py-1 text-xs text-white/65"
                    style={{ background: `${accentColor}15`, border: `1px solid ${accentColor}25` }}>
                    {s.name}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* Quote */}
          {featuredQuote && (
            <div className="mx-6 mt-5 rounded-xl px-4 py-3"
              style={{ background: `${accentColor}10`, border: `1px solid ${accentColor}20` }}>
              <p className="text-[13px] leading-relaxed text-white/60 italic">&ldquo;{featuredQuote}&rdquo;</p>
            </div>
          )}

          {/* CTA */}
          {ctaLabel && ctaUrl && (
            <div className="px-6 pt-5">
              <a href={ctaUrl} target="_blank" rel="noopener noreferrer"
                className="flex w-full items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-bold text-white transition-all hover:opacity-90 active:scale-[0.98]"
                style={{
                  background: `linear-gradient(135deg, ${accentColor}, #06b6d4)`,
                  boxShadow: `0 8px 24px ${accentColor}50`,
                }}>
                {ctaLabel} <Icon d={SVG_PATHS.arrow} size={15} />
              </a>
            </div>
          )}

          <div className="mt-5 flex items-center justify-between border-t border-white/5 px-6 py-3.5">
            <span className="text-[10px] text-white/20">PresenceCard</span>
            <div className="flex items-center gap-1.5">
              <div className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
              <span className="text-[10px] text-white/30">Active</span>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
